INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李仁矩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：李仁矩，客省使、传诏者。", "biography": null, "status": "draft", "id": "fb21d40c-5ef9-5374-a24e-96cf32ff0ba4"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "高郁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：高郁。", "biography": null, "status": "draft", "id": "5c9c4658-2c67-5ef1-bcde-997099768500"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "周廷望", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：周廷望，提出结交方案的典客。", "biography": null, "status": "draft", "id": "b3936771-6638-5e4b-8616-bdb9207d30d5"}, {"name": "周宗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：周宗。", "biography": null, "status": "draft", "id": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}, {"name": "徐知询", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明四年条所见人物：徐知询。", "biography": null, "status": "draft", "id": "1089abce-2d47-5761-8699-b3f0a21ecadc"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "武虔裕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：武虔裕，绵州刺史、率兵赴治者。", "biography": null, "status": "draft", "id": "bb699bea-1909-564d-83fa-030d7d807d0c"}]'::jsonb)
