INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "客将", "description": "李仁矩曾是李嗣源在藩镇时的客将。具体任职年月未载，不据此推定终身从属。", "status": "draft", "id": "7e7fb224-983d-58b3-ae35-4c1b12b156eb", "person_a": "fb21d40c-5ef9-5374-a24e-96cf32ff0ba4", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"relation_type": "谋臣", "description": "高郁曾任马殷的主要谋臣、都军判官。此条是追叙，未单列任用年份。", "status": "draft", "id": "3d160930-c79d-51d8-afcd-890cf94f3343", "person_a": "5c9c4658-2c67-5ef1-bcde-997099768500", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "朋友", "description": "周廷望与周宗交好。关系依929年条所追述的交往记录，不扩为终身政治盟友。", "status": "draft", "id": "d925d8e5-fff5-508f-8826-eb1dd4be4ac2", "person_a": "b3936771-6638-5e4b-8616-bdb9207d30d5", "person_b": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}, {"relation_type": "典客", "description": "周廷望是徐知询的典客。此条说明入朝争权前的任职，起止年月未载。", "status": "draft", "id": "b18a9f04-6418-5cf4-9808-d02205a42e94", "person_a": "b3936771-6638-5e4b-8616-bdb9207d30d5", "person_b": "1089abce-2d47-5761-8699-b3f0a21ecadc"}, {"relation_type": "亲吏", "description": "周宗是徐知诰的亲信官吏。徐知诰沿用李昪主体；此时为吴国任职关系，不提前称南唐君臣。", "status": "draft", "id": "b1c43974-3702-5da4-81d6-fec4aee68724", "person_a": "155e76cd-ab0e-5e2a-a791-43d64ebe4669", "person_b": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"relation_type": "旧部", "description": "武虔裕曾在李嗣源手下任职。具体年月、职务起止未载，不推定永久从属。", "status": "draft", "id": "a4ad9ea0-2ae7-5bef-b866-cf2c3533245f", "person_a": "bb699bea-1909-564d-83fa-030d7d807d0c", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

